-- >>> 99_inserts/09_horarios.sql
-- Grade de exemplo (slots de 1 hora) para as quadras 1 e 2:
--   segunda a sexta (1-5): 17h às 22h
--   sábado e domingo (6, 0): 9h às 21h
INSERT INTO horarios (quadra_id, dia_semana, hora_inicio, hora_fim)
SELECT q.id, d.dia, SEC_TO_TIME(h.hora * 3600), SEC_TO_TIME((h.hora + 1) * 3600)
FROM (SELECT 1 AS id UNION ALL SELECT 2) q
CROSS JOIN (SELECT 0 AS dia UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3
            UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6) d
CROSS JOIN (SELECT 9 AS hora UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12
            UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16
            UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20
            UNION ALL SELECT 21) h
WHERE (d.dia BETWEEN 1 AND 5 AND h.hora BETWEEN 17 AND 21)
   OR (d.dia IN (0, 6) AND h.hora BETWEEN 9 AND 20);


-- >>> 99_inserts/10_demo_empresas_quadras.sql
-- GERADO a partir dos dados de demonstração que ficavam no front (bah_quadras_web/src/data).
-- Empresas, quadras e grades de horários de demonstração.
SET NAMES utf8mb4;

INSERT INTO empresas (id, nome, cnpj, telefone, endereco, perfil, created_at) VALUES
    (2, 'Arena Sport', '12345678000190', '51987654321', 'Rua das Esmeraldas, 120 - Centro, Viamão/RS', '{"slogan":"Seu jogo começa aqui.","telefone":"(51) 98765-4321","whatsapp":"(51) 98765-4321","email":"contato@arenasport.com","instagram":"@arenasport","site":"arenasport.com.br","descricao":"Somos um complexo esportivo em Viamão com campos de society, quadra coberta de futsal e arena de areia. Estrutura completa para você reunir os amigos, treinar o time ou organizar campeonatos.","endereco":{"rua":"Rua das Esmeraldas","numero":"120","bairro":"Centro","cidade":"Viamão","estado":"RS","cep":"94400-000"},"verificada":true,"logo":"⚽","capa":"https://images.unsplash.com/photo-1518604666860-9ed391f76460?auto=format&fit=crop&w=1000&q=80","fotos":["https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1518604666860-9ed391f76460?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1592656094267-764a45160876?auto=format&fit=crop&w=1000&q=80"],"comodidades":["Estacionamento","Vestiário","Chuveiro","Iluminação LED","Lanchonete","Wi-Fi","Churrasqueira","Acessibilidade"],"pagamentos":["Pix","Cartão de crédito","Cartão de débito","Dinheiro"],"politicaCancelamento":"Cancelamento gratuito até 24 horas antes do horário reservado. Depois disso, é cobrado 50% do valor.","horarios":[{"dia":1,"nome":"Segunda","abre":"08:00","fecha":"23:00"},{"dia":2,"nome":"Terça","abre":"08:00","fecha":"23:00"},{"dia":3,"nome":"Quarta","abre":"08:00","fecha":"23:00"},{"dia":4,"nome":"Quinta","abre":"08:00","fecha":"23:00"},{"dia":5,"nome":"Sexta","abre":"08:00","fecha":"00:00"},{"dia":6,"nome":"Sábado","abre":"08:00","fecha":"00:00"},{"dia":0,"nome":"Domingo","abre":"09:00","fecha":"20:00"}],"bairro":"Centro","cidade":"Viamão/RS"}', NOW() - INTERVAL 461 DAY),
    (3, 'Quadra Center', NULL, NULL, 'Avenida Central, 450 - Santa Isabel, Viamão/RS', '{"descricao":"A Quadra Center é ideal para partidas de futsal. Possui espaço coberto, piso adequado para a prática esportiva e ambiente preparado para receber grupos e equipes.","bairro":"Santa Isabel","cidade":"Viamão/RS"}', NOW() - INTERVAL 200 DAY),
    (4, 'Play Sports', NULL, NULL, 'Rua dos Esportes, 80 - Menino Deus, Porto Alegre/RS', '{"descricao":"A Play Sports oferece uma excelente estrutura para quem gosta de vôlei de areia. Um ambiente descontraído para praticar esportes e aproveitar com os amigos.","bairro":"Menino Deus","cidade":"Porto Alegre/RS"}', NOW() - INTERVAL 200 DAY),
    (5, 'Arena Basketball', NULL, NULL, 'Av. Bento Gonçalves, 2100 - Partenon, Porto Alegre/RS', '{"descricao":"Quadra de basquete coberta com piso emborrachado, tabelas oficiais e iluminação de LED. Perfeita para treinos e partidas entre amigos.","bairro":"Partenon","cidade":"Porto Alegre/RS"}', NOW() - INTERVAL 200 DAY),
    (6, 'Beach Arena', NULL, NULL, 'Av. Guaíba, 3500 - Ipanema, Porto Alegre/RS', '{"descricao":"Quadras de areia à beira do Guaíba, com aluguel de raquetes e bolinhas. O lugar certo para jogar beach tennis no fim de tarde.","bairro":"Ipanema","cidade":"Porto Alegre/RS"}', NOW() - INTERVAL 200 DAY),
    (7, 'Gol de Ouro', NULL, NULL, 'Rua Dona Alzira, 900 - Sarandi, Porto Alegre/RS', '{"descricao":"Dois campos de society com grama sintética nova, churrasqueira e espaço para confraternização depois do jogo.","bairro":"Sarandi","cidade":"Porto Alegre/RS"}', NOW() - INTERVAL 200 DAY),
    (8, 'Tênis Clube Figueira', NULL, NULL, 'Rua Carlos Trein Filho, 640 - Três Figueiras, Porto Alegre/RS', '{"descricao":"Três quadras de saibro e uma de piso rápido, cercadas de verde. Aluguel de raquetes, máquina de bolinhas e professores para aulas avulsas.","bairro":"Três Figueiras","cidade":"Porto Alegre/RS"}', NOW() - INTERVAL 200 DAY),
    (9, 'Smash Badminton Club', NULL, NULL, 'Av. Flores da Cunha, 1200 - Vila Imbuí, Cachoeirinha/RS', '{"descricao":"Ginásio com quatro quadras oficiais de badminton, piso emborrachado e iluminação sem reflexo. Empresta raquetes e petecas para quem está começando.","bairro":"Vila Imbuí","cidade":"Cachoeirinha/RS"}', NOW() - INTERVAL 200 DAY),
    (10, 'Campo do Parque Society', NULL, NULL, 'Rua Tiradentes, 455 - Centro, Canoas/RS', '{"descricao":"Campo de society ao lado do parque, com grama sintética, refletores de LED e bar com telão para ver o jogo do Grêmio ou do Inter depois da pelada.","bairro":"Centro","cidade":"Canoas/RS"}', NOW() - INTERVAL 200 DAY),
    (11, 'Garrafão 3x3', NULL, NULL, 'Rua Anápio Gomes, 980 - Morada do Vale, Gravataí/RS', '{"descricao":"Quadra de basquete 3x3 com cobertura, piso de alta aderência e som ambiente. Point da galera do basquete de rua na Região Metropolitana.","bairro":"Morada do Vale","cidade":"Gravataí/RS"}', NOW() - INTERVAL 200 DAY),
    (12, 'Ace Tênis Center', NULL, NULL, 'Rua General Osório, 720 - Hamburgo Velho, Novo Hamburgo/RS', '{"descricao":"Duas quadras cobertas de piso rápido (sintético), ótimas para jogar mesmo com chuva. Tem aluguel de raquetes, máquina de bolinhas e aulas para iniciantes.","bairro":"Hamburgo Velho","cidade":"Novo Hamburgo/RS"}', NOW() - INTERVAL 200 DAY),
    (13, 'Ginásio Rede Alta', NULL, NULL, 'Av. Protásio Alves, 3100 - Petrópolis, Porto Alegre/RS', '{"descricao":"Ginásio coberto com quadra oficial de vôlei, piso de madeira, rede com altura regulável (masculina e feminina) e placar eletrônico. O preço é pelo ginásio inteiro.","bairro":"Petrópolis","cidade":"Porto Alegre/RS"}', NOW() - INTERVAL 200 DAY),
    (14, 'Autódromo FuelTech Velopark - Kart', NULL, NULL, 'Rodovia BR-386, Km 430 - BR-386, Km 430, Nova Santa Rita/RS', '{"descricao":"Kart no Autódromo FuelTech Velopark (antigo Velopark), complexo de automobilismo a menos de 30 km de Porto Alegre que tem três pistas de kart. Um programa diferente para correr com os amigos, comemorar aniversários ou fazer eventos da empresa.","bairro":"BR-386, Km 430","cidade":"Nova Santa Rita/RS","mapa":"Autódromo FuelTech Velopark, Nova Santa Rita - RS"}', NOW() - INTERVAL 200 DAY),
    (15, 'Top Speed Kart', NULL, NULL, 'Av. Praia de Belas, 1212 - Menino Deus, Porto Alegre/RS', '{"descricao":"Kart indoor no prédio garagem do Shopping Praia de Belas, em Porto Alegre. Pista coberta: dá para correr com chuva ou sol, de dia ou de noite.","bairro":"Menino Deus","cidade":"Porto Alegre/RS","mapa":"Top Speed Kart, Shopping Praia de Belas, Porto Alegre - RS"}', NOW() - INTERVAL 200 DAY),
    (16, 'Kartódromo Internacional de Tarumã', NULL, NULL, 'Autódromo Internacional de Tarumã - Autódromo de Tarumã, Viamão/RS', '{"descricao":"Kartódromo junto ao Autódromo Internacional de Tarumã, em Viamão, o autódromo mais tradicional do Rio Grande do Sul (inaugurado em 1970). Recebe provas de kart do automobilismo gaúcho.","bairro":"Autódromo de Tarumã","cidade":"Viamão/RS","mapa":"Autódromo Internacional de Tarumã, Viamão - RS"}', NOW() - INTERVAL 200 DAY),
    (17, 'RGM Academy', NULL, NULL, 'Rua Nissin Castiel, 883 - Distrito Industrial, Gravataí/RS', '{"descricao":"A RGM Academy é um complexo esportivo e escola de futebol criado pelos ex-goleiros do Grêmio Galatto e Marcelo Grohe, com campos oficiais, academia e escola de goleiros.","bairro":"Distrito Industrial","cidade":"Gravataí/RS"}', NOW() - INTERVAL 200 DAY);

