    (13, 9, 9, 'Smash Badminton Club', 'Ginásio com quatro quadras oficiais de badminton, piso emborrachado e iluminação sem reflexo. Empresta raquetes e petecas para quem está começando.', 50, 'ativa', 'Emborrachado', 'coberta', NULL, '["Quadras oficiais","Empréstimo de raquetes","Vestiário","Bebedouro","Ar-condicionado"]', 'https://images.unsplash.com/photo-1626224583764-f87db24ac4ea?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1546519638-68e109498ffc?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'hora', NULL, NULL),
    (14, 10, 1, 'Campo do Parque Society', 'Campo de society ao lado do parque, com grama sintética, refletores de LED e bar com telão para ver o jogo do Grêmio ou do Inter depois da pelada.', 85, 'ativa', 'Grama sintética', 'descoberta', NULL, '["Estacionamento","Vestiário","Bar com telão","Iluminação de LED"]', 'https://images.unsplash.com/photo-1487466365202-1afdb86c764e?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1560272564-c83b66b1ad12?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1575361204480-aadea25e6e68?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'hora', NULL, NULL),
    (15, 11, 6, 'Garrafão 3x3', 'Quadra de basquete 3x3 com cobertura, piso de alta aderência e som ambiente. Point da galera do basquete de rua na Região Metropolitana.', 55, 'ativa', 'Madeira', 'descoberta', NULL, '["Quadra coberta","Som ambiente","Bebedouro","Bicicletário"]', 'https://images.unsplash.com/photo-1515523110800-9415d13b84a8?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1504450758481-7338eba7524a?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1519861531473-9200262188bf?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'hora', NULL, NULL),
    (16, 12, 7, 'Ace Tênis Center', 'Duas quadras cobertas de piso rápido (sintético), ótimas para jogar mesmo com chuva. Tem aluguel de raquetes, máquina de bolinhas e aulas para iniciantes.', 80, 'ativa', 'Saibro', 'coberta', NULL, '["Quadras cobertas","Piso rápido","Aluguel de raquetes","Vestiário","Estacionamento"]', 'https://images.unsplash.com/photo-1595435934249-5df7ed86e1c0?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1622163642998-1ea32b0bbc67?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1599586120429-48281b6f0ece?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'hora', NULL, NULL),
    (17, 13, 4, 'Ginásio Rede Alta', 'Ginásio coberto com quadra oficial de vôlei, piso de madeira, rede com altura regulável (masculina e feminina) e placar eletrônico. O preço é pelo ginásio inteiro.', 110, 'ativa', 'Madeira', 'coberta', NULL, '["Piso de madeira","Rede regulável","Placar eletrônico","Arquibancada","Vestiários"]', 'https://images.unsplash.com/photo-1547347298-4074fc3086f0?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1588492069485-d05b56b2831d?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'hora', NULL, NULL),
    (18, 14, 13, 'Autódromo FuelTech Velopark - Kart', 'Kart no Autódromo FuelTech Velopark (antigo Velopark), complexo de automobilismo a menos de 30 km de Porto Alegre que tem três pistas de kart. Um programa diferente para correr com os amigos, comemorar aniversários ou fazer eventos da empresa.', 90, 'ativa', 'Asfalto', 'descoberta', NULL, '["Pista de kart de locação","Karts para aluguel"]', 'https://images.unsplash.com/photo-1505570554449-69ce7d4fa36b?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1508550794981-ed0e94d56589?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'bateria', 15, 'Autódromo FuelTech Velopark, Nova Santa Rita - RS'),
    (19, 15, 13, 'Top Speed Kart', 'Kart indoor no prédio garagem do Shopping Praia de Belas, em Porto Alegre. Pista coberta: dá para correr com chuva ou sol, de dia ou de noite.', 70, 'ativa', 'Asfalto', 'coberta', NULL, '["Kart indoor","Pista coberta","No Shopping Praia de Belas"]', 'https://images.unsplash.com/photo-1508550794981-ed0e94d56589?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1505570554449-69ce7d4fa36b?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'bateria', 10, 'Top Speed Kart, Shopping Praia de Belas, Porto Alegre - RS'),
    (20, 16, 13, 'Kartódromo Internacional de Tarumã', 'Kartódromo junto ao Autódromo Internacional de Tarumã, em Viamão, o autódromo mais tradicional do Rio Grande do Sul (inaugurado em 1970). Recebe provas de kart do automobilismo gaúcho.', 120, 'ativa', 'Asfalto', 'descoberta', NULL, '["Pista de kart ao ar livre","Junto ao Autódromo de Tarumã"]', 'https://images.unsplash.com/photo-1505570554449-69ce7d4fa36b?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1508550794981-ed0e94d56589?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'bateria', 20, 'Autódromo Internacional de Tarumã, Viamão - RS'),
    (21, 17, 12, 'RGM Academy - Campo Sintético', 'Campo oficial de futebol 11 com grama sintética e iluminação. A RGM Academy é um complexo esportivo e escola de futebol criado pelos ex-goleiros do Grêmio Galatto e Marcelo Grohe, com campos oficiais, academia e escola de goleiros.', 300, 'ativa', 'Grama sintética', 'descoberta', NULL, '["Grama sintética","Iluminação","Academia","Sala de fisioterapia","6 vestiários","Espaço para treino de goleiros"]', 'https://images.unsplash.com/photo-1551958219-acbc608c6377?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1518604666860-9ed391f76460?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'hora', NULL, NULL),
    (22, 17, 11, 'RGM Academy - Futebol 7', 'Campo de futebol 7, ideal para jogar com a galera. A RGM Academy é um complexo esportivo e escola de futebol criado pelos ex-goleiros do Grêmio Galatto e Marcelo Grohe, com campos oficiais, academia e escola de goleiros.', 180, 'ativa', 'Grama sintética', 'descoberta', NULL, '["Academia","Sala de fisioterapia","6 vestiários","Espaço para treino de goleiros"]', 'https://images.unsplash.com/photo-1518604666860-9ed391f76460?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1551958219-acbc608c6377?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'hora', NULL, NULL),
    (23, 17, 10, 'RGM Academy - Quadras de Areia', 'Duas quadras de areia para esportes como beach tennis e futevôlei. A RGM Academy é um complexo esportivo e escola de futebol criado pelos ex-goleiros do Grêmio Galatto e Marcelo Grohe, com campos oficiais, academia e escola de goleiros.', 80, 'ativa', 'Areia', 'descoberta', NULL, '["Academia","Sala de fisioterapia","6 vestiários","Espaço para treino de goleiros"]', 'https://images.unsplash.com/photo-1612872087720-bb876e2e67d1?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1592656094267-764a45160876?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1622163642998-1ea32b0bbc67?auto=format&fit=crop&w=1000&q=80"]', FALSE, 'hora', NULL, NULL);

